for(const[mode,kind,values,url,method]of [['edit','department',profileValues,'/api/hr/people/syn-person','PATCH'],['invite','department',inviteValues,'/api/hr/people/invitations/send','POST'],['structure','department',structureValues,'/api/hr/people/departments','POST'],['structure','designation',structureValues,'/api/hr/people/designations','POST']])check(`${mode}/${kind} saves exact existing route method and payload`,async h=>{const vm=ready(h,{mode,kind,values});h.response(()=>ok({id:'syn-created',email:'invite@example.invalid',email_sent:true}));await vm.save();assert.equal(h.requests.length,1);assert.equal(h.requests[0].url,url);assert.equal(h.requests[0].options.method,method);assert.deepEqual(JSON.parse(h.requests[0].options.body),originalPayload(mode==='edit'?'updatePerson':mode==='invite'?'invite':'addStructure',values));assert.equal(h.render().committed,true);assert.equal(h.api().dirty,false);assert.ok(h.guardCalls.some(c=>c.kind==='clean'));if(mode!=='invite')assert.deepEqual(h.navigation[0][2],{discard:true,replace:true});});
for(const mode of ['edit','invite','structure'])check(`${mode} failed write retains all fields and dirty state without navigating`,async h=>{const values=mode==='edit'?profileValues:mode==='invite'?inviteValues:structureValues;const vm=ready(h,{mode,values});h.response(()=>fail(422,'Synthetic denied'));await vm.save();const after=h.render();assert.deepEqual(after.values,values);assert.equal(after.committed,false);assert.equal(after.dirty,true);assert.equal(after.saving,false);assert.equal(after.error,'Synthetic denied');assert.equal(h.navigation.length,0);});
for(const mode of ['edit','invite','structure'])check(`${mode} synchronous duplicate save guard permits one mutation`,async h=>{const values=mode==='edit'?profileValues:mode==='invite'?inviteValues:structureValues,vm=ready(h,{mode,values});let resolve;h.response(()=>new Promise(r=>resolve=r));const first=vm.save();await vm.save();vm.change('notes','Must not mutate pending input');assert.deepEqual(h.state('values'),values);assert.equal(h.requests.length,1);resolve(ok({email_sent:true}));await first;await h.render().save();assert.equal(h.requests.length,1);});
for(const navMode of ['false','throw'])check(`known committed profile with navigation ${navMode} cannot be submitted twice`,async h=>{const vm=ready(h,{mode:'edit',values:profileValues});if(navMode==='false')h.navFail(true);else h.navThrow(true);await vm.save();let after=h.render();assert.equal(after.committed,true);assert.equal(after.dirty,false);await after.save();after.change('notes','forbidden');assert.deepEqual(h.state('values'),profileValues);assert.equal(h.requests.length,1);if(navMode==='throw')assert.match(after.error,/saved.*do not submit/);});
check('Cancel respects dirty refusal and input restoration becomes clean without any writes',h=>{let vm=ready(h,{mode:'edit'});assert.equal(vm.dirty,false);vm.change('notes','Changed');vm=h.render();assert.equal(vm.dirty,true);h.confirm(false);vm.back();assert.equal(h.navigation.length,0);assert.equal(h.state('values').notes,'Changed');vm.change('notes',person.notes);vm=h.render();assert.equal(vm.dirty,false);vm.back();assert.match(h.navigation[0][1],/\/people\/syn-person\?/);assert.equal(h.requests.length,0);});
check('successful invitation email hides the raw token and remains committed without automatic delivery retry',async h=>{const vm=ready(h,{mode:'invite',values:inviteValues});h.response(()=>ok({id:'syn-created',email:'invite@example.invalid',email_sent:true,invite_token:'synthetic-secret-not-used'}));await vm.save();const after=h.render();assert.equal(after.inviteLink,null);assert.deepEqual(h.clipboard,[]);assert.match(after.message,/email sent/);assert.equal(h.navigation.length,0);await after.save();assert.equal(h.requests.length,1);});
for(const clipboardFailure of [false,true])check(`created invitation delivery failure preserves manual fallback with clipboard failure=${clipboardFailure}`,async h=>{const vm=ready(h,{mode:'invite',values:inviteValues});h.clipboardFail(clipboardFailure);h.response(()=>ok({id:'syn-created',email:'invite@example.invalid',email_sent:false,invite_token:'synthetic/token with spaces'}));await vm.save();const after=h.render();assert.equal(after.committed,true);assert.equal(after.dirty,false);assert.equal(after.inviteLink,'https://example.invalid/invite/synthetic%2Ftoken%20with%20spaces');assert.match(after.message,clipboardFailure?/link below/:/link was copied/);assert.equal(h.clipboard.length,clipboardFailure?0:1);assert.equal(h.navigation.length,0);});
check('malformed invitation success is still a known commit, never a duplicate create opportunity',async h=>{const vm=ready(h,{mode:'invite',values:inviteValues});h.response(()=>ok(null));await vm.save();const after=h.render();assert.equal(after.committed,true);assert.equal(after.inviteLink,null);assert.match(after.message,/created.*details were unavailable.*do not submit again/);await after.save();assert.equal(h.requests.length,1);});
for(const action of ['copy','resend','revoke'])check(`${action} invitation action uses original POST endpoint and no invented body`,async h=>{const vm=ready(h);h.response((url,options)=>options?.method?ok({invite_token:'synthetic-fresh-token',email_sent:action==='resend'}):ok(action==='revoke'?{...bundle,invitations:[]}:bundle));await vm.inviteAction(invitation,action);assert.equal(h.requests[0].url,'/api/hr/people/invitations/syn-invitation/'+(action==='copy'?'link':action));assert.equal(h.requests[0].options.method,'POST');assert.equal(h.requests[0].options.body,undefined);assert.equal(h.requests[1].url,'/api/hr/people');const after=h.render();assert.equal(after.actionKey,null);if(action==='copy')assert.match(after.inviteLink,/synthetic-fresh-token$/);else assert.equal(after.inviteLink,null);});
check('revoke Cancel makes no request and retains the current visible link',async h=>{ready(h);h.set('inviteLink','https://example.invalid/invite/synthetic-old');const vm=h.render();h.confirm(false);await vm.inviteAction(invitation,'revoke');assert.equal(h.requests.length,0);assert.equal(h.state('inviteLink'),'https://example.invalid/invite/synthetic-old');});
for(const action of ['copy','resend','revoke'])check(`${action} clears previous token immediately and does not restore it after failure`,async h=>{ready(h);h.set('inviteLink','https://example.invalid/invite/synthetic-old');const vm=h.render();let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=vm.inviteAction(invitation,action);assert.equal(h.state('inviteLink'),null);assert.equal(h.state('actionKey'),`${invitation.id}:${action}`);resolve(fail(409,'Synthetic no longer pending'));await pending;assert.equal(h.state('inviteLink'),null);assert.equal(h.state('error'),'Synthetic no longer pending');assert.equal(h.state('actionKey'),null);assert.equal(h.requests.length,1);});
check('invitation actions reject capability loss and rows absent from the current bundle',async h=>{let vm=ready(h,{bundleValue:{...bundle,capabilities:{...bundle.capabilities,can_invite_employees:false}}});await vm.inviteAction(invitation,'copy');vm=ready(h);await vm.inviteAction({...invitation,id:'unknown'},'resend');assert.equal(h.requests.length,0);});
check('simultaneous token mutations are serialized across different rows and forms',async h=>{const other={...invitation,id:'other'},vm=ready(h,{bundleValue:{...bundle,invitations:[invitation,other]}});let resolve;h.response((_url,options)=>options?.method?new Promise(r=>resolve=r):ok(bundle));const pending=vm.inviteAction(invitation,'copy');await vm.inviteAction(other,'revoke');vm.changeBrowse({view:'structure'});assert.equal(h.requests.length,1);assert.equal(h.navigation.length,0);resolve(ok({invite_token:'synthetic-new-token'}));await pending;});
check('resend email failure keeps the replacement link, not the invalid previous token',async h=>{ready(h);h.set('inviteLink','https://example.invalid/invite/obsolete-synthetic');const vm=h.render();h.response((_url,options)=>options?.method?ok({email_sent:false,invite_token:'synthetic-replacement'}):ok(bundle));await vm.inviteAction(invitation,'resend');const after=h.render();assert.equal(after.inviteLink,'https://example.invalid/invite/synthetic-replacement');assert.match(after.message,/Email could not be sent.*Fresh invitation link copied/);});
check('committed token rotation plus failed directory GET is reported as readback failure, not a failed write',async h=>{const vm=ready(h);h.response((_url,options)=>options?.method?ok({invite_token:'synthetic-new-token'}):fail(500,'Synthetic readback failure'));await vm.inviteAction(invitation,'copy');const after=h.render();assert.match(after.error,/action completed.*directory could not be refreshed.*do not repeat/);assert.equal(after.bundle,null);assert.equal(after.inviteLink,null);await after.inviteAction(invitation,'copy');assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);});
check('late invitation token after unmount cannot be displayed or written to clipboard',async h=>{const vm=ready(h);const cleanup=effect(h,/mounted.current = true/);await settle();h.render();let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=vm.inviteAction(invitation,'copy');cleanup();resolve(ok({invite_token:'synthetic-late-token'}));await pending;assert.equal(h.state('inviteLink'),null);assert.deepEqual(h.clipboard,[]);assert.equal(h.state('message'),null);});
