check('copying the existing visible URL is clipboard-only and dismissing makes it unavailable',async h=>{ready(h);h.set('inviteLink','https://example.invalid/invite/synthetic-visible');const vm=h.render();await vm.copyVisibleInviteLink();assert.deepEqual(h.clipboard,['https://example.invalid/invite/synthetic-visible']);assert.equal(h.requests.length,0);vm.dismissInviteLink();await h.render().copyVisibleInviteLink();assert.equal(h.clipboard.length,1);});
