check('busy form and invitation writes activate the shared exit guard before a second UI action',async h=>{let vm=ready(h,{mode:'edit',values:profileValues});let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=vm.save();vm=h.render();assert.equal(h.guardCalls.at(-1).options.isBusy,true);h.confirm(true);vm.back();assert.equal(h.navigation.length,0);resolve(fail());await pending;});
const componentFile='src/components/people/people-workspace.tsx';
check('company, membership, role, permissions, pathname and structure kind remount sensitive People state',h=>{const key=()=>h.component(componentFile,'PeopleWorkspace',{}).key;let previous=key();for(const update of [()=>h.tenant('second-company'),()=>h.membership('second-membership'),()=>h.role('second-role'),()=>h.permissions(['hr.view']),()=>h.pathname('/dashboard/hr/people/new'),()=>h.query('kind=designation')]){update();const next=key();assert.notEqual(next,previous);previous=next;}assert.equal(h.requests.length,0);});
check('register profile/editor and committed recovery are mutually exclusive rendering states',h=>{ready(h);let tree=h.component(componentFile,'PeopleContent',{});assert.equal(nodes(tree,'PeopleRegister').length,1);assert.equal(nodes(tree,'PeopleEditor').length,0);assert.equal(nodes(tree,'PersonDocument').length,0);ready(h,{mode:'profile'});tree=h.component(componentFile,'PeopleContent',{});assert.equal(nodes(tree,'PersonDocument').length,1);assert.equal(nodes(tree,'PeopleRegister').length,0);ready(h,{mode:'edit'});tree=h.component(componentFile,'PeopleContent',{});assert.equal(nodes(tree,'PeopleEditor').length,1);assert.equal(nodes(tree,'PeopleRegister').length,0);h.render();h.set('committed',true);tree=h.component(componentFile,'PeopleContent',{});assert.equal(nodes(tree,'CommittedResult').length,1);assert.equal(nodes(tree,'PeopleEditor').length,0);});
