check('directory retains seven columns, one row mapping, searchable loaded-scope and row focus identity',h=>{const vm=ready(h),tree=h.component(componentFile,'PeopleDirectory',{vm});assert.deepEqual(nodes(tree,'th').map(text),['Person','Team','Role','Type','Status','Location','Profile']);assert.equal(nodes(tree,'PersonRow').length,1);assert.match(text(tree),/not records beyond the 1,000-person limit/);const row=h.component(componentFile,'PersonRow',{person,vm});assert.equal(row.props.id,'people-person-'+person.id);assert.equal(row.props.tabIndex,-1);for(const button of nodes(row,'button'))button.props.onClick();assert.equal(h.navigation.length,2);assert.ok(h.navigation.every(n=>n[1].startsWith('/dashboard/hr/people/syn-person?')));assert.equal(h.requests.length,0);});
