check('manager profile document retains original editable HR details but no inline mutation form',h=>{const vm=ready(h,{mode:'profile'}),tree=h.component(componentFile,'PersonDocument',{vm});assert.equal(nodes(tree,'form').length,0);assert.equal(nodes(tree,'input').length,0);const facts=nodes(tree,'Fact').map(n=>n.props.label);for(const label of ['Department','Designation','Manager','Work location','Employment type','Status','Join date','End date','Work email','Phone','Work phone','Login email','Workspace role','Membership status'])assert.ok(facts.includes(label),label);assert.match(text(tree),/Synthetic internal note/);assert.ok(nodes(tree,'button').some(n=>text(n).includes('Edit profile')));});
