check('profile fields preserve original option mappings including active-employed manager with suspended access',h=>{const vm=ready(h,{mode:'edit',bundleValue:{...bundle,people:peopleFixtures}}),tree=h.component(componentFile,'ProfileFields',{vm});const selects=nodes(tree,'SearchableSelect');for(const name of ['departmentOptions','designationOptions','managerOptions']){const field={departmentOptions:'department_id',designationOptions:'designation_id',managerOptions:'manager_employee_id'}[name];assert.deepEqual(selects.find(n=>n.props.name===field).props.options,originalExpression(name,{bundle:vm.bundle,editing:person}));}assert.ok(selects.find(n=>n.props.name==='manager_employee_id').props.options.some(n=>n.value==='suspended'));assert.equal(nodes(tree,'select')[0].props.name,'employment_type');assert.deepEqual(nodes(tree,'option').map(n=>n.props.value),['full_time','part_time','contract','internship','temporary']);for(const n of selects){const fresh=h.component(componentFile,'ProfileFields',{vm:h.render()});nodes(fresh,'SearchableSelect').find(field=>field.props.name===n.props.name).props.onValueChange('synthetic-choice');}assert.equal(h.render().values.manager_employee_id,'synthetic-choice');});
check('all eleven profile editable fields remain present, with email/date types and no role or status editor',h=>{const vm=ready(h,{mode:'edit'}),tree=h.component(componentFile,'ProfileFields',{vm}),fields=[...nodes(tree,'SearchableSelect'),...nodes(tree,'select'),...nodes(tree,'Field'),...nodes(tree,'TextArea')];assert.deepEqual(fields.map(n=>n.props.name).sort(),h.load(path.join(root,modelFile)).PERSON_FIELDS.slice().sort());assert.equal(nodes(tree,'Field').find(n=>n.props.name==='work_email').props.type,'email');for(const name of ['join_date','end_date'])assert.equal(nodes(tree,'Field').find(n=>n.props.name===name).props.type,'date');});
check('invitation form retains six fields, required name/email and restricted nonclearable role options',h=>{const vm=ready(h,{mode:'invite'}),tree=h.component(componentFile,'InvitationFields',{vm});const fields=[...nodes(tree,'SearchableSelect'),...nodes(tree,'Field')];assert.deepEqual(fields.map(n=>n.props.name).sort(),['full_name','email','role_id','department_id','designation_id','employee_code'].sort());for(const name of ['full_name','email'])assert.equal(fields.find(n=>n.props.name===name).props.required,true);const role=fields.find(n=>n.props.name==='role_id');assert.equal(role.props.required,true);assert.equal(role.props.clearable,false);assert.deepEqual(role.props.options,originalExpression('roleOptions',{bundle}));});
