check('actual shared People guard refuses dirty Cancel and preserves unload protection after accepted preflight',h=>{const events=new EventTarget();global.window.addEventListener=events.addEventListener.bind(events);global.window.removeEventListener=events.removeEventListener.bind(events);global.window.dispatchEvent=events.dispatchEvent.bind(events);const hook=h.load(path.join(root,'src/hooks/use-quotation-navigation-guard.ts')).useQuotationNavigationGuard;const guard=hook(true,{documentLabel:'people'});const cleanups=h.effects.map(fn=>fn()).filter(Boolean);h.confirm(false);assert.equal(guard.confirmLeave(),false);assert.equal(h.prompts[0],'You have unsaved people changes. Discard them and leave this page?');const exit=h.load(path.join(root,'src/lib/workspace-navigation.ts')).requestWorkspaceExit;assert.equal(exit(),false);h.confirm(true);assert.equal(exit(),true);const unload=new Event('beforeunload',{cancelable:true});global.window.dispatchEvent(unload);assert.equal(unload.defaultPrevented,true);cleanups.forEach(fn=>fn());});
