check('successful invitation result is never encoded into navigation context',async h=>{const vm=ready(h,{mode:'invite',values:inviteValues});h.response(()=>ok({email_sent:false,invite_token:'synthetic-opaque-token'}));await vm.save();h.render().openSaved();assert.equal(h.navigation.length,1);assert.match(h.navigation[0][1],/^\/dashboard\/hr\/people\?view=invitations$/);assert.ok(h.navigation.every(n=>!String(n[1]).includes('synthetic-opaque-token')));assert.equal(h.requests.length,1);});
check('new and edit entry callbacks use document navigation rather than unguarded router pushes',h=>{let vm=ready(h,{mode:'profile'});vm.openEdit();assert.equal(h.navigation[0][0],'navigate');assert.match(h.navigation[0][1],/\/syn-person\/edit\?/);vm=ready(h);vm.openCreate('invite');assert.equal(h.navigation[1][0],'navigate');assert.match(h.navigation[1][1],/\/people\/new\?/);assert.equal(h.requests.length,0);});
check('native directory Edit retains list filter and focus but is absent for readers',h=>{h.query('search=Syn');let vm=ready(h),tree=h.component(componentFile,'PersonRow',{person,vm}),edit=nodes(tree,'a')[0];assert.ok(edit);assert.equal(new URLSearchParams(edit.props.href.split('?')[1]).get('returnTo'),'/dashboard/hr/people?search=Syn&focus=syn-person');assert.match(edit.props.href,/\/syn-person\/edit\?/);vm=ready(h,{bundleValue:{...bundle,capabilities:{...bundle.capabilities,can_manage_people:false}}});tree=h.component(componentFile,'PersonRow',{person,vm});assert.equal(nodes(tree,'a').length,0);assert.equal(nodes(tree,'button').filter(n=>text(n).includes('View')).length,1);});
for(const kind of ['department','designation'])check(`${kind} creation is hidden from structure readers`,h=>{const vm=ready(h,{bundleValue:{...bundle,capabilities:{...bundle.capabilities,can_manage_structure:false}}}),tree=h.component(componentFile,'StructureRegister',{vm,title:'Structure',rows:bundle.departments,kind});assert.equal(nodes(tree,'button').length,0);assert.match(text(tree),/Engineering/);});
check('actual shared People guard blocks busy navigation and workspace exit even when user would consent',h=>{const events=new EventTarget();global.window.addEventListener=events.addEventListener.bind(events);global.window.removeEventListener=events.removeEventListener.bind(events);global.window.dispatchEvent=events.dispatchEvent.bind(events);const hook=h.load(path.join(root,'src/hooks/use-quotation-navigation-guard.ts')).useQuotationNavigationGuard,guard=hook(false,{documentLabel:'people',isBusy:true});const cleanups=h.effects.map(fn=>fn()).filter(Boolean);h.confirm(true);assert.equal(guard.navigate('/dashboard/hr',{discard:true}),false);assert.equal(h.load(path.join(root,'src/lib/workspace-navigation.ts')).requestWorkspaceExit(),false);assert.equal(h.prompts.length,0);assert.equal(h.navigation.length,0);cleanups.forEach(fn=>fn());});
check('directory-only profile never broadens visibility to internal notes, phones, manager, dates or login security facts',h=>{const vm=ready(h,{mode:'profile',bundleValue:{...bundle,capabilities:{...bundle.capabilities,can_manage_people:false}}}),tree=h.component(componentFile,'PersonDocument',{vm}),facts=nodes(tree,'Fact');assert.deepEqual(facts.map(n=>n.props.label),['Department','Designation','Work location','Employment type','Status','Contact email']);assert.equal(facts.find(n=>n.props.label==='Contact email').props.value,person.work_email);assert.doesNotMatch(text(tree),/Synthetic internal note|Internal HR note|Workspace identity/);assert.equal(nodes(tree,'button').length,0);assert.equal(nodes(tree,'form').length,0);assert.match(text(tree),/same information as the team directory/);});
check('directory-only preferred email falls back to login email only when the work address is absent',h=>{const vm=ready(h,{mode:'profile',bundleValue:{...bundle,people:[{...person,work_email:null}],capabilities:{...bundle.capabilities,can_manage_people:false}}}),tree=h.component(componentFile,'PersonDocument',{vm});assert.equal(nodes(tree,'Fact').find(n=>n.props.label==='Contact email').props.value,person.login_email);assert.equal(nodes(tree,'Fact').some(n=>n.props.label==='Login email'),false);});
check('invitation capability denied hides pending summary rather than misrepresenting hidden data as zero',h=>{const vm=ready(h,{bundleValue:{...bundle,capabilities:{...bundle.capabilities,can_invite_employees:false}}}),tree=h.component(componentFile,'PeopleSummary',{vm});for(const surface of [...nodes(tree,'section'),...nodes(tree,'details')])assert.deepEqual(nodes(surface,'Summary').map(n=>n.props.label),['People','Active','Departments']);});
check('person View cannot programmatically leave while an invitation write is pending',async h=>{let vm=ready(h);let resolve;h.response((_url,options)=>options?.method?new Promise(r=>resolve=r):ok(bundle));const pending=vm.inviteAction(invitation,'copy');vm=h.render();vm.openPerson(person.id);assert.equal(h.navigation.length,0);resolve(ok({invite_token:'synthetic-token'}));await pending;});
check('mobile snapshot is a closed native disclosure retaining the same complete authorized metrics as desktop',h=>{const vm=ready(h,{bundleValue:{...bundle,people:peopleFixtures}}),tree=h.component(componentFile,'PeopleSummary',{vm}),desktop=nodes(tree,'section')[0],mobile=nodes(tree,'details')[0];assert.ok(mobile);assert.equal(mobile.props.open,undefined);assert.match(text(nodes(mobile,'summary')[0]),/4 people.*2 active/);assert.deepEqual(nodes(mobile,'Summary').map(n=>[n.props.label,n.props.value]),nodes(desktop,'Summary').map(n=>[n.props.label,n.props.value]));assert.match(text(mobile),/up to 1,000 people and 100 pending invitations/);});

// Actual hook lifecycle regressions: synthetic requests only, never real invitations.
for(const transition of ['unmount','company','membership','role','permission','route'])check(`retained People save/load/token actions cannot dispatch after ${transition}`,async h=>{
 const old=ready(h,{mode:'structure',values:structureValues});
 if(transition==='unmount')h.layoutUnmount();else{if(transition==='company')h.tenant('replacement');if(transition==='membership')h.membership('replacement');if(transition==='role')h.role('replacement');if(transition==='permission')h.permissions(['hr.view']);if(transition==='route')h.pathname('/dashboard/hr/people/new');h.render();}
 await old.save();await old.load();await old.inviteAction(invitation,'resend');old.change('name','stale');old.openCreate('invite');assert.equal(h.requests.length,0);assert.equal(h.navigation.length,0);
});
for(const status of [401,200])check(`dismissed People read ${status} cannot redirect or install results`,async h=>{
 ready(h);let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=h.api().load();h.layoutUnmount();resolve(status===401?fail(401):ok({...bundle,people:[]}));await pending;assert.equal(h.navigation.length,0);assert.equal(h.state('bundle'),bundle);
});
for(const mode of ['edit','invite','structure'])for(const result of ['network',408,429,500,'malformed422'])check(`unknown ${mode} ${result} locks same document even after readonly refresh`,async h=>{
 const values=mode==='edit'?profileValues:mode==='invite'?inviteValues:structureValues;
 const old=ready(h,{mode,values});h.response((_u,o)=>o?.method?result==='network'?Promise.reject(Error('synthetic transport loss')):result==='malformed422'?{ok:false,status:422,json:async()=>{throw Error('synthetic unreadable body');}}:fail(result):ok(bundle));
 await old.save();let current=h.render();assert.equal(current.outcome,'unknown');assert.equal(current.unresolved,true);current.change('notes','must remain frozen');await current.load();current=h.render();await current.save();await old.save();assert.equal(h.requests.filter(r=>r.options?.method).length,1);assert.deepEqual(current.values,values);assert.equal(current.outcome,'unknown');
});
for(const action of ['copy','resend','revoke'])check(`unknown ${action} never automatically rotates/resends/revokes after refresh`,async h=>{
 const old=ready(h);h.response((_u,o)=>o?.method?Promise.reject(Error('synthetic lost reply')):ok(bundle));await old.inviteAction(invitation,action);await h.render().load();let current=h.render();await current.inviteAction(invitation,action);await old.inviteAction(invitation,action);assert.equal(h.requests.filter(r=>r.options?.method).length,1);assert.equal(current.unresolved,true);assert.equal(current.inviteLink,null);assert.deepEqual(h.clipboard,[]);
});
check('same-event draft change invalidates retained Save and old setter without losing current draft',async h=>{
 const old=ready(h,{mode:'structure',values:structureValues});old.change('name','Fresh draft');await old.save();old.change('name','Old handler');assert.equal(h.requests.length,0);assert.equal(h.state('values').name,'Fresh draft');await h.render().save();assert.equal(h.requests.length,1);
});
check('dismissed visible invitation link cannot be copied by retained handler',async h=>{
 ready(h);h.set('inviteLink','https://example.invalid/invite/synthetic-old');const old=h.render();old.dismissInviteLink();await old.copyVisibleInviteLink();assert.equal(h.clipboard.length,0);
});
check('2xx before interrupted body retains commit and never resubmits',async h=>{
 const old=ready(h,{mode:'invite',values:inviteValues});h.response(()=>({ok:true,status:201,json:async()=>{throw Error('synthetic body loss');}}));await old.save();const current=h.render();assert.equal(current.committed,true);await current.save();assert.equal(h.requests.length,1);assert.match(current.message,/created.*details were unavailable/);
});
check('closed/reopened same People route cannot revive prior draft handlers',async h=>{
 const old=ready(h,{mode:'structure',values:structureValues});h.pathname('/dashboard/hr/people');h.render();h.pathname('/dashboard/hr/people/structure/new');h.render();h.set('values',{...structureValues,name:'Reopened fresh draft'});h.render();old.change('name','Discarded old input');await old.save();assert.equal(h.requests.length,0);assert.equal(h.state('values').name,'Reopened fresh draft');
});
for(const mode of ['save','resend'])for(const result of ['401','token'])check(`pending ${mode} late ${result} cannot affect replacement owner`,async h=>{
 const old=ready(h,{mode:mode==='save'?'invite':'register',values:inviteValues});let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=mode==='save'?old.save():old.inviteAction(invitation,'resend');h.tenant('new-company');h.render();resolve(result==='401'?fail(401):ok({email_sent:false,invite_token:'synthetic-old-token'}));await pending;assert.equal(h.navigation.length,0);assert.equal(h.clipboard.length,0);assert.equal(h.state('inviteLink'),null);
});
check('unknown People outcome visibly disables editor and invitation buttons with readonly review link',h=>{
 const base=ready(h,{mode:'structure',values:structureValues}),vm={...base,unresolved:true,outcome:'unknown'};
 const form=h.component(componentFile,'PeopleEditor',{vm});assert.equal(nodes(form,'fieldset')[0].props.disabled,true);
 const action=h.component(componentFile,'InvitationAction',{vm,row:invitation,action:'resend',label:'Resend email',icon:'Icon'});assert.equal(nodes(action,'button')[0].props.disabled,true);
 h.render();h.set('outcome','unknown');const page=h.component(componentFile,'PeopleContent',{});const link=nodes(page,'a').find(n=>text(n)==='Review records in a new tab');assert.ok(link);assert.equal(link.props.target,'_blank');assert.equal(link.props.rel,'noopener noreferrer');assert.match(text(page),/later list does not prove.*Reloading or leaving loses/s);
});
for(const mode of ['edit','structure'])test(`People actual shared navigation guard allows only acknowledged current ${mode} exit`,async()=>{
 const h=harness('usePeopleWorkspace','src/hooks/use-people-workspace.ts',{actualGuard:true});try{
  const old=ready(h,{mode,values:mode==='edit'?profileValues:structureValues});let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=old.save();old.back();assert.equal(h.navigation.length,0);await old.save();assert.equal(h.requests.length,1);
  resolve(ok({id:'syn-created'}));await pending;assert.equal(h.navigation.length,1);assert.equal(h.navigation[0][0],'location.replace');assert.match(h.navigation[0][1],/\/dashboard\/hr\/people/);await h.render().save();assert.equal(h.requests.length,1);
 }finally{h.cleanup();}
});
test('People actual shared navigation guard keeps unknown pristine action guarded after settled failure',async()=>{
 const h=harness('usePeopleWorkspace','src/hooks/use-people-workspace.ts',{actualGuard:true});try{
  const old=ready(h);h.response(()=>Promise.reject(Error('synthetic lost response')));await old.inviteAction(invitation,'resend');h.render();effect(h,/dirtyRef.current = hasChanges/);h.confirm(false);h.api().back();assert.equal(h.navigation.length,0);assert.equal(h.prompts.length,1);assert.match(h.prompts[0],/may already have completed/);assert.equal(h.requests.length,1);
 }finally{h.cleanup();}
});
